// TH15 v1.00b Extra / st07bs.ecl.txt Boss2 (source 194-262).
// Source-frame 0 is the boss enemy's first run.  In the measured run the shell
// spawns it at card frame 124 (phase/pattern/next-frame startup), so source t
// maps to card frame about 124+t; see report.md.
//
// Source entry state (st07bs.ecl.txt:8-39, 196-205): spawn at the Boss's
// movePos(0,128), hurtbox 40 -> r20, hitbox 48 -> r24, and the 504 limit
// (0,128,280,64) = x in [-140,140], y in [96,160].  HP reset is 20400
// (st07bs.ecl.txt:197).  Source flags 47/35/64/3 resolve to offscreen-keep and
// the unknown 0x40 bit only (no target bit, boss stays in limit); no write.
// The shell keeps the enemy invulnerable permanently and does not restore DPS.

const TIME_LIMIT: int = 3724;   // 120 opening + 3600 window + 4 startup margin
const OPENING_BUFFER: int = 120;
const TH15_KUNAI: int = 496;   // source etSprite type 9, color 6
const BULLET_COLOR: int = 6;

// Source Boss2_at / Boss2_at2: RANDRAD in [-pi,pi], then +-1 degree per volley.
// Deltas in source radians -> BAM: 0.022689281 -> 237 (1.3deg),
// 0.027925268 -> 291 (1.6deg), 0.10472 -> 1092 (6deg), 0.017453 -> 182 (1deg).
// Mode 10 with two layers has H = delta/2 on both layers (aim-modes.md); the
// layer-0 ring base is A+H and layer-1 is the mirrored ring (base A-H, same
// increasing ring order as a set).
const H13: int = 118;          // 1.3deg / 2
const H16: int = 146;          // 1.6deg / 2
const H10: int = 91;           // 1.0deg / 2
const D10: int = 182;          // 1.0deg
const D60: int = 1092;         // 6.0deg

// ANIM birth displacement is kept while the birth animation itself is omitted
// (transcription-policy.md): net sh_dist = source etDist - 4*initial speed.
const AT_DIST_V2: fx = 16fx;   // etDist 24 - 4*2
const AT_DIST_V4: fx = 8fx;    // etDist 24 - 4*4
const AT2_DIST_V1: fx = -4fx;  // source etDist(0,24) is on emitter 0, so emitter 1 dist 0 - 4*1

// ---- Source 412 moveRand(60, 4, 1.9) at st07bs.ecl.txt:257 ---------------
// Same verified sample as the TH16/TH18 recipe (movement.md): speed ramps
// linearly from 1.9 to 0 over 60 ticks, per-tick final position clamped by the
// 504 rectangle, no bounce. The target integrates movement after ECL, so the
// next source movement tick is armed one frame early (movement.md).

sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = 1.9fx * ((60 - k) as fx) / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }   // moveLimit(0,128,280,64)
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub card_move_rand() {
    // Signed unit random * pi, in unwrapped BAM units (movement.md).
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }   // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // intentionally not normalized before the source fabs tests
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad = 522 BAM (nearest boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- Source Boss2_at, st07bs.ecl.txt:264-297 (emitter 0) ------------------
// etAim mode 10, 25 ways x 2 layers, etAngle delta 1.3deg then 1.6deg,
// etSpeed 2 then 4, 10 volleys of 5 frames each per phase, A +1deg/-1deg.
async sub boss2_at() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 25, 1);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, AT_DIST_V2);
    var a: angle = (rand(65536) - 32768) as angle;   // %A = %RANDRAD
    for i in 0..10 {
        // mode10 layer q=0: alpha + R(i) + H; q=1: alpha - R(i) - H
        sh_angle(0, a + (H13 as angle), 0deg);
        sh_speed(0, 2fx, 0fx);
        sh_dist(0, AT_DIST_V2);
        sh_fire(0);
        sh_angle(0, a - (H13 as angle), 0deg);
        sh_fire(0);
        a = a + (D10 as angle);
        wait(5);
    }
    for j in 0..10 {
        sh_angle(0, a + (H16 as angle), 0deg);
        sh_speed(0, 4fx, 0fx);
        sh_dist(0, AT_DIST_V4);
        sh_fire(0);
        sh_angle(0, a - (H16 as angle), 0deg);
        sh_fire(0);
        a = a - (D10 as angle);
        wait(5);
    }
}

// ---- Source Boss2_at2, st07bs.ecl.txt:299-333 (emitter 1) -----------------
// etAim mode 10, 10 ways x 2 layers, delta 1deg, speed 1, 10 volleys at -6deg
// then an extra -1deg and 10 volleys at +6deg.
async sub boss2_at2() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 10, 1);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 1fx, 0fx);
    sh_dist(0, AT2_DIST_V1);
    var a: angle = (rand(65536) - 32768) as angle;   // %A = %RANDRAD
    for i in 0..10 {
        sh_angle(0, a + (H10 as angle), 0deg);
        sh_speed(0, 1fx, 0fx);
        sh_dist(0, AT2_DIST_V1);
        sh_fire(0);
        sh_angle(0, a - (H10 as angle), 0deg);
        sh_fire(0);
        a = a - (D60 as angle);
        wait(5);
    }
    a = a - (D10 as angle);   // source line 0321
    for j in 0..10 {
        sh_angle(0, a + (H10 as angle), 0deg);
        sh_speed(0, 1fx, 0fx);
        sh_dist(0, AT2_DIST_V1);
        sh_fire(0);
        sh_angle(0, a - (H10 as angle), 0deg);
        sh_fire(0);
        a = a + (D60 as angle);
        wait(5);
    }
}

// ---- Source Boss2 body, st07bs.ecl.txt:194-262 ---------------------------
async sub boss2_main() {
    set_invuln(65535);   // source 120; shell keeps the boss invulnerable
    set_hitbox(24fx);    // Boss 501 setHitbox(48,48)
    set_hurtbox(20fx);   // Boss 500 setHurtbox(40,40)

    wait(4);             // source time labels 0 -> 2 -> 4
    // t=4: timerReset, setInterrupt(0,3400,3600,"BossCard2"), killAllAsync,
    // enmKillAll, etCancel/etClear, spellEnd, funcSet(0), laserCancel.
    // Independent card starts empty; the timeout is carried by TIME_LIMIT,
    // the HP-succession target is the next card boundary (not transcribed).
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);   // t=4, source 401 mode 4 from (0,128)
    wait(120);           // t=124, ends source animation segment
    wait(60);            // t=184
    // t=184 source 504 moveLimit(0,128,280,64): enforced every moveRand tick
    wait(60);            // source +20 block, t=244

    // Source window: 3600 frames from timerReset at t=4, so the attack loop
    // runs at t=244+160*k for k=0..20 (21 waves) and the next wave would be
    // the t=3604 timeout. Do not start a 22nd wave beyond the source segment.
    for wave in 0..21 {
        spawn boss2_at();
        spawn boss2_at2();
        wait(100);
        card_move_rand();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 20400, 0, 0, 0, boss2_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
